+      else if (event.key === 'ArrowUp') next = (index - 1 + options.length) % options.length;
+      else if (event.key === 'Home') next = 0;
+      else if (event.key === 'End') next = options.length - 1;
+      else if (event.key === 'Enter' || event.key === ' ') {
+        event.preventDefault();
+        options[index].click();
+        return;
+      } else if (event.key === 'Escape') {
+        event.preventDefault();
+        closeRoasts(true);
+        return;
+      } else if (/^[a-z]$/i.test(event.key)) {
+        next = options.findIndex(option => option.dataset.value.startsWith(event.key.toLowerCase()));
+        if (next === -1) return;
+      }
+      if (next !== undefined) {
+        event.preventDefault();
+        options[next].focus();
+      }
+    });
+
+    selector.addEventListener('focusout', event => {
+      if (!selector.contains(event.relatedTarget)) closeRoasts();
+    });
+    document.addEventListener('click', event => {
+      if (!selector.contains(event.target)) closeRoasts();
+    });
+  </script>
 </body>

 </html>

