+const formatters = new Map();
+function partsAt(timestamp,tz){
+ if(!formatters.has(tz)) formatters.set(tz,new Intl.DateTimeFormat('en-GB',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}));
+ return Object.fromEntries(formatters.get(tz).formatToParts(new Date(timestamp)).filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]));
