+function offsetLabel(timestamp,tz){const minutes=offsetAt(timestamp,tz)/60000;return 'UTC'+(minutes>=0?'+':'−')+String(Math.floor(Math.abs(minutes)/60)).padStart(2,'0')+':'+String(Math.abs(minutes)%60).padStart(2,'0')}
