+ $('cityCount').textContent=`${selectedCities.length} cities`;
+ $('copyButton').disabled=eventInstant===null;
+ if(eventInstant===null){$('grid').innerHTML='';return;}
+ const hostParts=partsAt(eventInstant,hostTz);
+ const hostDay=Date.UTC(hostParts.year,hostParts.month-1,hostParts.day);
+ eventDetails=`The Daily Grind · Global coffee tasting\n${fmt(eventInstant,hostTz,{weekday:'long',month:'long',day:'numeric',year:'numeric'})}\nHost: ${fmt(eventInstant,hostTz,{hour:'numeric',minute:'2-digit'})} (${hostTz}, ${offsetLabel(eventInstant,hostTz)})\n\n`;
