+ const time=tparts.filter(p=>p.type==='hour'||p.type==='minute'||p.type==='literal').map(p=>p.value).join('').trim();
+ const period=tparts.find(p=>p.type==='dayPeriod').value;
+ const date=fmt(eventInstant,c.tz,{weekday:'short',month:'short',day:'numeric'});
+ const shortZone=fmt(eventInstant,c.tz,{timeZoneName:'short'}).split(', ').pop().split(' ').pop();
