+ return `<article class="city-card ${host?'host':''}" aria-label="${c.city}, ${time} ${period}, ${date}"><div class="city-top"><span class="country">${c.country.toUpperCase()}</span><span class="city-symbol">${icon(daytime?'sun':'moon')}</span></div><h3>${c.city}</h3><div class="city-time">${time}<span class="meridiem">${period}</span></div><div class="city-date">${date}${dayDifference?`<span class="day-badge">${dayDifference>0?'+':''}${dayDifference} day${Math.abs(dayDifference)>1?'s':''}</span>`:''}</div><div class="card-bottom"><span class="tz-label">${shortZone} <span style="opacity:.65">·</span> ${offsetLabel(eventInstant,c.tz)}</span>${host?`<span class="host-badge">${icon('cup')} Your time</span>`:`<span class="offset ${!daytime?'off-hours':''}">${relative}</span>`}</div></article>`;
