+$('eventForm').addEventListener('submit',e=>{e.preventDefault();update(false)});
+$('addButton').addEventListener('click',()=>{const available=cities.filter(c=>!selectedCities.includes(c));$('citySelect').innerHTML='';available.forEach(c=>$('citySelect').add(new Option(`${c.city} — ${c.country}`,c.tz)));$('confirmCity').disabled=!available.length;$('cityDialog').showModal()});
