+  <script>
+    const copyTimers = new WeakMap();
+    let lastCopyMessage = '';
+
+    function reportCopy(button, succeeded) {
+      const status = button.nextElementSibling;
+      clearTimeout(copyTimers.get(button));
+      let message = succeeded ? 'Copied!' : 'Copy failed. Please select and copy the description manually.';
+      if (message === lastCopyMessage) message += '\u00a0';
+      lastCopyMessage = message;
+      status.textContent = message;
+      copyTimers.set(button, setTimeout(() => {
+        status.textContent = '';
+      }, 4000));
+    }
+
+    async function copyDescription(button, target) {
+      try {
+        await navigator.clipboard.writeText(target.innerText.trim());
+        reportCopy(button, true);
+      } catch {
+        reportCopy(button, false);
+      }
+    }
+
+    if ('CommandEvent' in window) {
+      // Command events do not bubble, so listen during capture.
+      document.addEventListener('command', (event) => {
+        if (event.command === '--copy') {
+          copyDescription(event.source, event.target);
+        }
+      }, true);
+    } else {
+      document.addEventListener('click', (event) => {
+        const button = event.target.closest('button[command="--copy"]');
+        if (!button) return;
+        const target = document.getElementById(button.getAttribute('commandfor'));
+        if (target) copyDescription(button, target);
+      });
+    }
+  </script>
 </body>

