+#include <stdint.h>
+static int width, height, row, pass, target;
+static uint32_t renderSeed;
+static Vec* accumulation = nullptr;
+static unsigned char* pixels = nullptr;
+extern "C" {
+void setup(int w, int h, int spp, unsigned int seed) {
+  width=w; height=h; row=0; pass=0; target=spp/4; renderSeed=seed;
+  delete[] accumulation; delete[] pixels;
