+  pixels = new unsigned char[w*h*4]();
+  for (int i=0;i<w*h;i++) pixels[i*4+3]=255;
+}
+void set_color(int sphere, double r, double g, double b) {
+  if (sphere>=0 && sphere<2) spheres[6+sphere].c=Vec(r,g,b);
+}
