+}
+unsigned char* get_pixels() { return pixels; }
+double get_progress() { return double(pass*height+row)/(target*height); }
+}
+#ifndef __EMSCRIPTEN__
+int main(int argc, char** argv) {
+  int w=argc>1?atoi(argv[1]):640, h=w*3/4, spp=argc>2?atoi(argv[2]):64;
+  setup(w,h,spp,42);
+  set_color(0,.78,.66,.94); set_color(1,.66,.92,.78);
