diff --git a/public/wasm/render-worker.js b/public/wasm/render-worker.js
new file mode 100644
index 0000000..e0c0643
--- /dev/null
+++ b/public/wasm/render-worker.js
@@ -0,0 +1,30 @@
+import createSmallpt from './smallpt.js';
+const ready = createSmallpt();
+let activeJob = 0;
+self.onmessage = async ({ data }) => {
+  const job = ++activeJob;
+  try {
+    const wasm = await ready;
+    if (job !== activeJob) return;
+    const { width, height, samples, seed, colors } = data;
+    wasm._setup(width, height, samples, seed);
+    colors.forEach((c, i) => wasm._set_color(i, ...c));
+    const start = performance.now();
+    let lastFrame = 0;
+    const tick = () => {
+      if (job !== activeJob) return;
+      try {
+        let done = false;
+        const until = performance.now() + 40;
+        do { done = !!wasm._render_rows(4); } while (!done && performance.now() < until);
+        if (done || (wasm._get_progress() >= 4 / samples && performance.now() - lastFrame > 180)) {
+          const pixels = new Uint8ClampedArray(wasm.HEAPU8.buffer, wasm._get_pixels(), width * height * 4).slice();
+          self.postMessage({ id: data.id, pixels, width, height, progress: wasm._get_progress(), elapsed: performance.now() - start, done }, [pixels.buffer]);
+          lastFrame = performance.now();
+        }
+        if (!done) setTimeout(tick, 0);
+      } catch (error) { self.postMessage({ id: data.id, error: String(error) }); }
+    };
+    tick();
+  } catch (error) { self.postMessage({ id: data.id, error: String(error) }); }
+};
