+#!/usr/bin/env bash
+set -euo pipefail
+cd "$(dirname "$0")/.."
+mkdir -p public/wasm
+em++ native/smallpt.cpp -o public/wasm/smallpt.js \
+  -O3 -flto -fno-exceptions -Wall -Werror --no-entry \
