+/* Later layers take precedence; keep component defaults easy to override. */
+@layer reset, tokens, base, layout, components, states;
+
+@layer reset {
+  :where(*, *::before, *::after) {
+    box-sizing: border-box;
+  }
+
+  :where(body, h1, h2, h3, p, ul) {
+    margin: 0;
+    padding: 0;
+  }
+}
+
+@layer tokens {
+  :root {
+    --color-brand: #4e342e;
+    --color-brand-strong: #3e2723;
+    --color-accent: #ffab40;
+    --color-text: #3e2723;
+    --color-page: #fafafa;
+    --color-surface: #fff;
+    --color-footer: #d7ccc8;
+    --color-on-brand: #fff;
+    --color-hero-overlay: rgb(0 0 0 / 50%);
+
+    --font-family-body: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+    --font-size-small: 0.85rem;
+    --font-size-nav: 0.9rem;
+    --font-size-logo: 1.5rem;
+    --font-size-hero: 3rem;
+    --font-weight-bold: 700;
+    --line-height-body: 1.6;
+    --letter-spacing-logo: 0.0625rem;
+
+    --space-1: 0.3125rem;
+    --space-2: 0.625rem;
+    --space-3: 0.75rem;
+    --space-4: 0.9375rem;
+    --space-5: 1rem;
+    --space-6: 1.25rem;
+    --space-7: 2.5rem;
+
+    --radius-small: 0.25rem;
+    --radius-button: 0.3125rem;
+    --radius-card: 0.5rem;
+    --border-width: 1px;
+    --shadow-card: 0 2px 5px rgb(0 0 0 / 10%);
+    --duration-interaction: 0.3s;
+    --content-max: 68.75rem;
+    --card-min: 15.625rem;
+    --nav-gutter: 5%;
+    --hero-height: 60vh;
+    --layer-sticky: 1000;
+    --image-hero: url('https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=1350&q=80');
+  }
+}
+
+@layer base {
+  body {
+    font-family: var(--font-family-body);
+    line-height: var(--line-height-body);
+    color: var(--color-text);
+    background-color: var(--color-page);
+  }
+
+  :where(.site-nav a, .site-footer a, .btn) {
+    text-decoration: none;
+  }
+}
+
+@layer layout {
+  .container {
+    max-inline-size: var(--content-max);
+    margin-block: var(--space-7);
+    margin-inline: auto;
+    padding-inline: var(--space-6);
+  }
+
+  .grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--card-min)), 1fr));
+    gap: var(--space-6);
+    margin-block-start: var(--space-6);
+  }
+}
+
+@layer components {
+  :where(.site-nav, .hero) {
+    display: flex;
+    align-items: center;
+    color: var(--color-on-brand);
+  }
+
+  .site-nav {
+    position: sticky;
+    inset-block-start: 0;
+    z-index: var(--layer-sticky);
+    flex-wrap: wrap;
+    justify-content: space-between;
+    gap: var(--space-5) var(--space-6);
+    padding-block: var(--space-5);
+    padding-inline: var(--nav-gutter);
+    background: var(--color-brand);
+  }
+
+  .logo {
+    font-size: var(--font-size-logo);
+    font-weight: var(--font-weight-bold);
+    letter-spacing: var(--letter-spacing-logo);
+  }
+
+  .site-nav :where(ul) {
+    display: flex;
+    flex-wrap: wrap;
+    gap: var(--space-2) var(--space-6);
+    list-style: none;
+  }
+
+  .site-nav :where(a) {
+    color: inherit;
+    font-size: var(--font-size-nav);
+    transition: color var(--duration-interaction);
+  }
+
+  .logout-link {
+    border: var(--border-width) solid var(--color-accent);
+    padding-block: var(--space-1);
+    padding-inline: var(--space-3);
+    border-radius: var(--radius-small);
+  }
+
+  .hero {
+    block-size: var(--hero-height);
+    flex-direction: column;
+    justify-content: center;
+    padding-inline: var(--space-6);
+    background-image: linear-gradient(var(--color-hero-overlay), var(--color-hero-overlay)), var(--image-hero);
+    background-size: cover;
+    background-position: center;
+  }
+
+  .hero :where(h1) {
+    margin-block-end: var(--space-5);
+    font-size: var(--font-size-hero);
+  }
+
+  :where(.hero, .section-title, .card, .site-footer) {
+    text-align: center;
+  }
+
+  .card {
+    padding: var(--space-6);
+    background: var(--color-surface);
+    border-radius: var(--radius-card);
+    box-shadow: var(--shadow-card);
+  }
+
+  .card :where(h3) {
+    margin-block-end: var(--space-2);
+    color: var(--color-brand);
+  }
+
+  .btn {
+    display: inline-block;
+    margin-block-start: var(--space-4);
+    padding-block: var(--space-2);
+    padding-inline: var(--space-6);
+    background: var(--color-brand);
+    color: var(--color-on-brand);
+    border-radius: var(--radius-button);
+    transition: background-color var(--duration-interaction);
+  }
+
+  .site-footer {
+    margin-block-start: var(--space-7);
+    padding-block: var(--space-7);
+    padding-inline: var(--space-6);
+    background: var(--color-footer);
+  }
+
+  .footer-links {
+    margin-block-end: var(--space-6);
+  }
+
+  .footer-links :where(a) {
+    margin-inline: var(--space-2);
+    color: var(--color-text);
+    font-size: var(--font-size-small);
+  }
+}
+
+@layer states {
+  .site-nav :where(a:is(:hover, :focus-visible)) {
+    color: var(--color-accent);
+  }
+
+  .btn:where(:hover, :focus-visible) {
+    background-color: var(--color-brand-strong);
+  }
+
+  :where(a:focus-visible) {
+    outline: 2px solid currentColor;
+    outline-offset: var(--space-1);
+  }
+
+  @media (prefers-reduced-motion: reduce) {
+    :where(.site-nav a, .btn) {
+      transition: none;
+    }
+  }
+}

