diff --git a/index.html b/index.html
index 66c9173..54b245a 100644
--- a/index.html
+++ b/index.html
@@ -135,6 +135,122 @@
       background: #3e2723;
     }

+    .sr-only {
+      position: absolute;
+      width: 1px;
+      height: 1px;
+      padding: 0;
+      margin: -1px;
+      overflow: hidden;
+      clip-path: inset(50%);
+      white-space: nowrap;
+      border: 0;
+    }
+
+    .drink-preview {
+      display: inline-block;
+    }
+
+    .btn:focus-visible,
+    .preview-close:focus-visible,
+    .preview-link:focus-visible {
+      outline: 3px solid var(--accent);
+      outline-offset: 4px;
+    }
+
+    .hovercard {
+      position: fixed;
+      z-index: 1100;
+      width: min(340px, calc(100vw - 24px));
+      max-height: calc(100dvh - 24px);
+      overflow-y: auto;
+      padding: 24px;
+      border: 1px solid var(--secondary);
+      border-radius: 12px;
+      background: #fffdf9;
+      box-shadow: 0 12px 40px rgba(62, 39, 35, 0.2);
+      text-align: left;
+    }
+
+    .preview-eyebrow {
+      margin-bottom: 8px;
+      padding-right: 24px;
+      color: #765c4f;
+      font-size: 0.7rem;
+      font-weight: 700;
+      letter-spacing: 0.12em;
+      text-transform: uppercase;
+    }
+
+    .hovercard h4 {
+      color: var(--primary);
+      font-size: 1.3rem;
+      line-height: 1.3;
+      margin-bottom: 10px;
+    }
+
+    .preview-description {
+      color: #66524a;
+      font-size: 0.9rem;
+    }
+
+    .preview-facts {
+      display: grid;
+      grid-template-columns: 1fr 1fr;
+      gap: 16px;
+      margin: 18px 0;
+      padding: 16px 0;
+      border-top: 1px solid #e9dfd6;
+      border-bottom: 1px solid #e9dfd6;
+      font-size: 0.85rem;
+    }
+
+    .preview-facts dt {
+      color: #765c4f;
+      font-size: 0.7rem;
+      margin-bottom: 3px;
+      text-transform: uppercase;
+      letter-spacing: 0.06em;
+    }
+
+    .preview-facts dd {
+      font-weight: 600;
+    }
+
+    .preview-close {
+      position: absolute;
+      top: 12px;
+      right: 12px;
+      width: 32px;
+      height: 32px;
+      border: 0;
+      border-radius: 50%;
+      background: transparent;
+      color: var(--primary);
+      font-size: 1.4rem;
+      cursor: pointer;
+    }
+
+    .preview-close:hover {
+      background: #f0e8df;
+    }
+
+    .preview-link {
+      display: flex;
+      justify-content: space-between;
+      align-items: center;
