+import { useEffect, useId, useRef, type ReactNode } from 'react';
+
+interface Props {
+  isOpen: boolean;
+  onClose: () => void;
+  title: string;
+  children: ReactNode;
+  focusClose?: boolean;
+}
+
+export default function Modal({ isOpen, onClose, title, children, focusClose = true }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  const titleId = useId();
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (isOpen && dialog && !dialog.open) dialog.showModal();
+    else if (!isOpen && dialog?.open) dialog.close();
+  }, [isOpen]);
+
+  return (
+    <dialog ref={dialogRef} aria-labelledby={titleId} closedBy="any"
+      onClose={onClose} className="overlay-dialog bg-white shadow-xl">
+      <div className="flex items-center justify-between gap-4 p-4 border-b border-gray-200">
+        <h2 id={titleId} className="text-lg font-semibold">{title}</h2>
+        <form method="dialog">
+          <button className="px-3 py-2 rounded hover:bg-gray-100" autoFocus={focusClose}>Close</button>
+        </form>
+      </div>
+      {isOpen && children}
+    </dialog>
+  );
+}
