new file mode 100644
index 0000000..eabf36a
--- /dev/null
+++ b/src/components/Modal.tsx
@@ -0,0 +1,35 @@
+import { useEffect, useRef, type ReactNode } from 'react';
+
+interface Props {
+  titleId: string;
+  onClose: () => void;
+  children: ReactNode;
+}
+
+/** Native modal behavior supplies focus containment, inert background and Escape. */
+export default function Modal({ titleId, onClose, children }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  useEffect(() => {
+    const dialog = dialogRef.current!;
+    const opener = document.activeElement;
+    dialog.showModal();
+    return () => {
+      dialog.close();
+      if (opener instanceof HTMLElement && opener.isConnected) opener.focus();
+    };
+  }, []);
+
+  return (
+    <dialog ref={dialogRef} aria-labelledby={titleId} className="site-dialog bg-white shadow-xl w-full max-w-2xl"
+      onClose={onClose}
+      onClick={event => {
+        if (event.target !== event.currentTarget) return;
+        const rect = event.currentTarget.getBoundingClientRect();
+        if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) {
+          event.currentTarget.close();
+        }
+      }}>
+      {children}
+    </dialog>
+  );
+}
