@@ -0,0 +1,33 @@
+const form = document.querySelector('#newsletter-form');
+const status = document.querySelector('#newsletter-status');
+const button = form.querySelector('button');
+
+form.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  if (button.disabled) return;
+  button.disabled = true;
+  status.textContent = 'Signing you up…';
+  const controller = new AbortController();
+  const timeout = setTimeout(() => controller.abort(), 15000);
+
+  try {
+    const response = await fetch('/api/newsletter', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+      body: JSON.stringify({ email: form.elements.email.value }),
+      credentials: 'same-origin',
+      redirect: 'error',
+      signal: controller.signal,
+    });
+    if (!response.ok) throw new Error('Signup failed');
+    const result = await response.json();
+    if (result.ok !== true) throw new Error('Signup not confirmed');
+    status.textContent = 'You’re signed up! Look out for news from Daily Grind.';
+    form.reset();
+  } catch {
+    status.textContent = 'We couldn’t complete your signup. The request may have been blocked or the connection interrupted. Please try again.';
+  } finally {
+    clearTimeout(timeout);
+    button.disabled = false;
+  }
+});
