+const allowedElements = ['p', 'br', 'strong', 'b', 'em', 'i', 'ul', 'ol', 'li', 'blockquote'];
+const drinks = new Map([
+  ['maple', 'Maple Oat Latte'],
+  ['espresso', 'Dark Roast Espresso'],
+  ['cold-brew', 'Cold Brew'],
+]);
+let purifierPromise;
+
+export async function renderReviewHTML(container, markup) {
+  if ('setHTML' in container) {
+    // Parse and sanitize in the destination context; never reparse sanitized nodes.
+    container.setHTML(markup, {
+      sanitizer: { elements: allowedElements, attributes: [], comments: false },
+    });
+    return;
+  }
+
+  // Keep a local, pinned fallback for browsers without the native Sanitizer API.
+  purifierPromise ??= import('./vendor/dompurify-3.4.17.mjs').then(({ default: purifier }) => purifier)
+    .catch((error) => {
+      purifierPromise = undefined;
+      throw error;
+    });
+  const purifier = await purifierPromise;
+  if (!purifier.isSupported) throw new Error('HTML sanitization is unavailable.');
+  const fragment = purifier.sanitize(markup, {
+    ALLOWED_TAGS: [...allowedElements, '#text'],
+    ALLOWED_ATTR: [],
+    ALLOW_ARIA_ATTR: false,
+    ALLOW_DATA_ATTR: false,
+    KEEP_CONTENT: false,
+    RETURN_DOM_FRAGMENT: true,
+  });
+  container.replaceChildren(fragment);
+}
+
+export function initializeReviews() {
+  const form = document.getElementById('review-form');
+  const feedback = document.getElementById('review-feedback');
+  const status = document.getElementById('review-status');
+  const button = form.querySelector('button[type="submit"]');
+  let submitting = false;
+
+  feedback.addEventListener('input', () => feedback.setCustomValidity(''));
+  form.addEventListener('submit', async (event) => {
+    event.preventDefault();
+    if (submitting || !form.reportValidity()) return;
+    const data = new FormData(form);
+    const drink = drinks.get(data.get('drink'));
+    if (!drink) return;
+    const markup = data.get('feedback');
+    const name = data.get('name').trim() || 'Anonymous';
+    if (markup.length > 5000 || name.length > 80) return;
+
+    submitting = true;
+    button.disabled = true;
+    status.textContent = 'Preparing your review…';
+    try {
+      const content = document.createElement('div');
+      content.className = 'review-content';
+      await renderReviewHTML(content, markup);
+      if (!content.textContent.trim()) {
+        feedback.setCustomValidity('Please include some review text using the supported formatting.');
+        feedback.reportValidity();
+        status.textContent = 'Your review needs some text after unsupported HTML is removed.';
+        return;
+      }
+
+      const item = document.createElement('li');
+      const article = document.createElement('article');
+      const heading = document.createElement('h4');
+      heading.textContent = drink;
+      const author = document.createElement('p');
+      author.textContent = `Reviewed by ${name}`;
+      article.append(heading, author, content);
+      item.append(article);
+      document.getElementById('review-list').prepend(item);
+      document.getElementById('reviews-empty').hidden = true;
+      feedback.value = '';
+      status.textContent = `Your review of ${drink} has been posted on this page.`;
+    } catch {
+      // Fail closed: never display raw markup if a sanitizer cannot run.
+      status.textContent = 'We could not safely display your review. Your draft is saved in the form; please try again.';
+    } finally {
+      submitting = false;
+      button.disabled = false;
+    }
+  });
+  form.hidden = false;
+}
+
+if (typeof document !== 'undefined') initializeReviews();
