+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { handleSignup } from '../src/server/signup.ts';
+import { normalizePhone } from '../src/utils/phone.ts';
+
+const config = { accountSid: 'account', authToken: 'secret', serviceSid: 'service', templateSid: 'template' };
+const phone = '+14155552671';
+const details = { action: 'register', username: 'reader', password: 'password1', phone, code: '012345' };
+const challenge = () => ({ phone, sid: 'challenge', expiresAt: Date.now() + 600000, verified: false });
+const request = (body: object, origin = 'https://news.example') => new Request('https://news.example/devtools-times/api/signup', {
+  method: 'POST', headers: { origin, 'Content-Type': 'application/json' }, body: JSON.stringify(body),
+});
+function session(initial: Record<string, unknown> = {}) {
+  const store = new Map(Object.entries(initial));
+  return { get: async (key: string) => store.get(key), set: (key: string, value: unknown) => { store.set(key, value); }, delete: (key: string) => { store.delete(key); } };
+}
+const neverFetch = async () => { throw new Error('Unexpected network request'); };
+
+test('normalizes international phone formatting without dropping country code', () => {
+  assert.equal(normalizePhone('+1 (415) 555-2671'), phone);
+});
+test('rejects cross-origin calls and unavailable configuration', async () => {
+  assert.equal((await handleSignup(request(details, 'https://other.example'), session(), config, neverFetch)).status, 403);
+  assert.equal((await handleSignup(request(details), session(), {}, neverFetch)).status, 503);
+});
+test('requires valid phone, credentials, challenge and matching number before registration', async () => {
+  for (const body of [{ ...details, phone: '4155552671' }, { ...details, password: 'short' }, details]) {
+    assert.equal((await handleSignup(request(body), session(), config, neverFetch)).status, 400);
+  }
+  const state = session({ signupChallenge: challenge() });
+  assert.equal((await handleSignup(request({ ...details, phone: '+442079460123' }), state, config, neverFetch)).status, 400);
+});
+test('sends via approved template, binds challenge, and enforces resend cooldown across numbers', async () => {
+  const state = session();
+  let calls = 0;
+  const fetcher: typeof fetch = async (_url, options) => {
+    calls++;
+    const body = options!.body as URLSearchParams;
+    assert.equal(body.get('To'), phone);
+    assert.equal(body.get('TemplateSid'), 'template');
+    return Response.json({ status: 'pending', sid: 'challenge' });
+  };
+  assert.equal((await handleSignup(request({ action: 'send', phone }), state, config, fetcher)).status, 200);
+  assert.equal((await state.get('signupChallenge') as any).phone, phone);
+  assert.equal((await handleSignup(request({ action: 'send', phone: '+442079460123' }), state, config, fetcher)).status, 429);
+  assert.equal(calls, 1);
+});
+test('invalid and expired codes never call registration', async () => {
+  for (const provider of [Response.json({ status: 'pending' }), Response.json({}, { status: 404 })]) {
+    let calls = 0;
+    const response = await handleSignup(request(details), session({ signupChallenge: challenge() }), config, async url => {
+      assert.match(String(url), /VerificationCheck$/);
+      calls++;
+      return provider;
+    });
+    assert.equal(response.status, 400);
+    assert.equal(calls, 1);
+  }
+  assert.equal((await handleSignup(request(details), session({ signupChallenge: { ...challenge(), expiresAt: 0 } }), config, neverFetch)).status, 400);
+});
+test('preserves leading zeros, registers only after approval and consumes challenge', async () => {
+  const state = session({ signupChallenge: challenge() });
+  const urls: string[] = [];
+  const response = await handleSignup(request(details), state, config, async (url, options) => {
+    urls.push(String(url));
+    if (urls.length === 1) {
+      assert.equal((options!.body as URLSearchParams).get('Code'), '012345');
+      assert.equal((options!.body as URLSearchParams).get('VerificationSid'), 'challenge');
+      return Response.json({ status: 'approved' });
+    }
+    assert.equal(JSON.parse(String(options!.body)).phone, phone);
+    return Response.json({});
+  });
+  assert.equal(response.status, 200);
+  assert.equal(urls.length, 2);
+  assert.equal(await state.get('signupChallenge'), undefined);
+  assert.equal((await handleSignup(request(details), state, config, neverFetch)).status, 400);
+});
+test('retains approved verification after registration failure so retry does not reuse consumed OTP', async () => {
+  const state = session({ signupChallenge: challenge() });
+  let calls = 0;
+  const first = await handleSignup(request(details), state, config, async () => {
+    calls++;
+    return calls === 1 ? Response.json({ status: 'approved' }) : Response.json({}, { status: 500 });
+  });
+  assert.equal(first.status, 502);
+  assert.equal((await state.get('signupChallenge') as any).verified, true);
+  const retry = await handleSignup(request(details), state, config, async url => {
+    assert.match(String(url), /api\/register$/);
+    return Response.json({});
+  });
+  assert.equal(retry.status, 200);
+});
+test('provider outage never produces a success response', async () => {
+  const response = await handleSignup(request({ action: 'send', phone }), session(), config, async () => { throw new Error('offline'); });
+  assert.equal(response.status, 502);
+});

