@@ -0,0 +1,113 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { createHash } from 'node:crypto';
+import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { generateKeyPair, exportJWK, SignJWT } from 'jose';
+import { createApp, createMemberStore } from '../lib/app.mjs';
+import { verifyEmailToken, publicJson } from '../lib/verification.mjs';
+
+const origin = 'https://coffee.example';
+const issuer = 'https://issuer.example';
+const email = 'Jamie@example.com';
+const nonce = 'test-single-use-nonce';
+const now = Math.floor(Date.now() / 1000);
+const issuerKeys = await generateKeyPair('ES256');
+const holderKeys = await generateKeyPair('ES256');
+const jwk = { ...await exportJWK(holderKeys.publicKey), alg: 'ES256' };
+const issuerJwk = await exportJWK(issuerKeys.publicKey);
+const deps = {
+  txt: async () => [['iss=issuer.example']],
+  json: async url => url.endsWith('/.well-known/email-verification') ? { issuer, jwks_uri: `${issuer}/keys` } : { keys: [issuerJwk] },
+};
+async function token({ claims = {}, kb = {}, signer = issuerKeys.privateKey, holderSigner = holderKeys.privateKey } = {}) {
+  const evt = await new SignJWT({ iss: issuer, email, email_verified: true, iat: now, exp: now + 300, cnf: { jwk }, ...claims }).setProtectedHeader({ alg: 'ES256', typ: 'ev+sd-jwt' }).sign(signer);
+  const hash = createHash('sha256').update(`${evt}~`).digest('base64url');
+  const binding = await new SignJWT({ iat: now, aud: origin, nonce, sd_hash: hash, ...kb }).setProtectedHeader({ alg: 'ES256', typ: 'kb+jwt' }).sign(holderSigner);
+  return `${evt}~${binding}`;
+}
+const check = rawToken => verifyEmailToken({ rawToken, email: email.toLowerCase(), nonce, audience: origin }, deps);
+test('accepts signed, provider-delegated, case-insensitive email ownership', async () => {
+  assert.equal((await check(await token())).email, email);
+});
+for (const [label, options] of [
+  ['unverified email', { claims: { email_verified: false } }],
+  ['different email', { claims: { email: 'someone@example.com' } }],
+  ['expired EVT', { claims: { exp: now - 120 } }],
+  ['missing expiry', { claims: { exp: undefined } }],
+  ['stale EVT', { claims: { iat: now - 600 } }],
+  ['wrong audience', { kb: { aud: 'https://attacker.example' } }],
+  ['wrong nonce', { kb: { nonce: 'stolen-nonce' } }],
+  ['wrong token binding', { kb: { sd_hash: 'incorrect' } }],
+  ['future binding', { kb: { iat: now + 600 } }],
+  ['invalid issuer signature', { signer: holderKeys.privateKey }],
+  ['invalid holder signature', { holderSigner: issuerKeys.privateKey }],
+]) test(`rejects ${label}`, async () => assert.rejects(() => token(options).then(check)));
+test('validates DNS delegation before requesting issuer metadata', async () => {
+  let fetched = false;
+  await assert.rejects(() => token().then(rawToken => verifyEmailToken({ rawToken, email, nonce, audience: origin }, { txt: async () => [['iss=attacker.example']], json: async () => { fetched = true; } })));
+  assert.equal(fetched, false);
+});
+test('supports issuer JWKS without kid and with multiple candidate keys', async () => {
+  const alt = { ...deps, json: async url => url.endsWith('/keys') ? { keys: [jwk, issuerJwk] } : deps.json(url) };
+  await verifyEmailToken({ rawToken: await token(), email, nonce, audience: origin }, alt);
+});
+test('rejects private and non-HTTPS provider destinations', async () => {
+  for (const url of ['http://issuer.example', 'https://127.0.0.1/keys', 'https://[::1]/keys', 'https://user:pass@example.com/keys']) await assert.rejects(() => publicJson(url));
+});
+
+async function formFixture(app) {
+  const response = await app(new Request(origin));
+  const html = await response.text();
+  return {
+    cookie: response.headers.get('set-cookie').split(';')[0],
+    nonce: html.match(/nonce="([^"]+)"/)[1],
+    formId: html.match(/name="formId" value="([^"]+)"/)[1],
+    response,
+  };
+}
+function submit(app, fixture, updates = {}, headers = {}) {
+  return app(new Request(`${origin}/api/verify-email`, { method: 'POST', headers: { Origin: origin, Cookie: fixture.cookie, 'Content-Type': 'application/x-www-form-urlencoded', ...headers }, body: new URLSearchParams({ firstName: 'Jamie', lastName: 'Morgan', email, formId: fixture.formId, token: 'signed-token', ...updates }) }));
+}
+test('renders a fresh server nonce and secure session cookie with no-store and configured trial', async () => {
+  const app = createApp({ origin, trialToken: 'trial-value', saveMember() {} });
+  const a = await formFixture(app); const b = await formFixture(app);
+  assert.notEqual(a.nonce, b.nonce);
+  assert.equal(a.response.headers.get('cache-control'), 'no-store');
+  assert.match(a.response.headers.get('set-cookie'), /HttpOnly; SameSite=Lax/);
+  assert.match(a.response.headers.get('set-cookie'), /Secure/);
+  assert.equal(a.response.headers.get('origin-trial'), 'trial-value');
+});
+test('saves only server-verified members and consumes a nonce exactly once', async () => {
+  const saved = [];
+  let expected;
+  const app = createApp({ origin, saveMember: member => saved.push(member), verify: async values => { assert.equal(values.nonce, expected); assert.equal(values.audience, origin); } });
+  const f = await formFixture(app); expected = f.nonce;
+  const responses = await Promise.all([submit(app, f, { marketing: 'yes' }), submit(app, f)]);
+  assert.deepEqual(responses.map(response => response.status), [200, 409]);
+  assert.equal(saved.length, 1); assert.equal(saved[0].marketing, true);
+});
+test('missing, invalid, or cookie-mismatched tokens never create members', async () => {
+  let count = 0;
+  const app = createApp({ origin, saveMember: () => { count++; }, verify: async () => { throw new Error('invalid'); } });
+  assert.equal((await submit(app, await formFixture(app), { token: '' })).status, 422);
+  assert.equal((await submit(app, await formFixture(app))).status, 422);
+  assert.equal((await submit(app, await formFixture(app), {}, { Cookie: 'dg_signup=wrong' })).status, 409);
+  assert.equal(count, 0);
+});
+test('rejects cross-origin and malformed submissions', async () => {
+  const app = createApp({ origin, saveMember() {} });
+  assert.equal((await submit(app, await formFixture(app), {}, { Origin: 'https://attacker.example' })).status, 403);
+  assert.equal((await submit(app, await formFixture(app), { email: 'invalid' })).status, 400);
+});
+test('persistent member store survives reopening and prevents duplicate email registration', () => {
+  const dir = mkdtempSync(join(tmpdir(), 'dg-test-'));
+  try {
+    const save = createMemberStore(dir);
+    save({ firstName: 'Jamie', lastName: 'Morgan', email });
+    createMemberStore(dir)({ firstName: 'Jamie', lastName: 'Morgan', email: email.toLowerCase() });
+    const members = JSON.parse(readFileSync(join(dir, 'members.json')));
+    assert.equal(members.length, 1); assert.equal(members[0].emailVerified, true);
+  } finally { rmSync(dir, { recursive: true, force: true }); }
+});

